<?php
/**
 * rollback.php — wp-legacy-media-optimizer
 *
 * Reverts everything scripts/convert_and_stage.php did: puts the original
 * files back (from the quarantine dir or the backup archive), restores
 * post_mime_type / _wp_attached_file / _wp_attachment_metadata, and rewrites
 * post_content URLs back to the original extension. Removes the generated
 * .webp files.
 *
 * Runs inside WordPress via WP-CLI eval-file — do NOT run with plain `php`.
 *
 * Usage:
 *   wp eval-file scripts/rollback.php <rollback.json> [--dry-run]
 *
 * Inputs:
 *   <rollback.json>   Manifest generated by convert_and_stage.php.
 *   --dry-run         Report what would be restored; change nothing.
 */

if ( ! defined( 'WP_CLI' ) || ! WP_CLI ) {
	fwrite( STDERR, "This script must run via WP-CLI: wp eval-file scripts/rollback.php <rollback.json> [--dry-run]\n" );
	exit( 1 );
}

/* ------------------------------------------------------------------ */
/* Argument parsing                                                    */
/* ------------------------------------------------------------------ */

$args = isset( $args ) && is_array( $args ) ? $args : array();

$opt = array(
	'json'    => null,
	'dry_run' => false,
);

foreach ( $args as $a ) {
	if ( '--dry-run' === $a ) {
		$opt['dry_run'] = true;
	} elseif ( 0 === strpos( $a, '--' ) ) {
		WP_CLI::warning( 'Ignoring unknown option ' . $a );
	} elseif ( null === $opt['json'] ) {
		$opt['json'] = $a;
	}
}

if ( null === $opt['json'] || ! is_readable( $opt['json'] ) ) {
	WP_CLI::error( 'Rollback manifest not found or not readable. Usage: wp eval-file scripts/rollback.php <rollback.json> [--dry-run]' );
}

$manifest = json_decode( file_get_contents( $opt['json'] ), true );
if ( ! is_array( $manifest ) || empty( $manifest['items'] ) || ! is_array( $manifest['items'] ) ) {
	WP_CLI::error( 'Invalid rollback manifest: missing "items".' );
}

/* ------------------------------------------------------------------ */
/* Helpers                                                             */
/* ------------------------------------------------------------------ */

$uploads = wp_get_upload_dir();
$baseurl = trailingslashit( $uploads['baseurl'] );
$basedir = trailingslashit( $uploads['basedir'] );

/**
 * Where convert_and_stage.php parks originals when --quarantine is used:
 * uploads/_legacy_quarantine/ with the relative path flattened to a name.
 */
function mo_quarantine_name( $rel_path ) {
	return preg_replace( '#[\\\\/]+#', '_', $rel_path );
}

/**
 * Read one member out of a .zip or .tar.gz backup archive.
 * Returns file contents (string) or false.
 */
function mo_archive_read( $archive, $member ) {
	if ( ! is_file( $archive ) ) {
		return false;
	}
	if ( 'zip' === strtolower( pathinfo( $archive, PATHINFO_EXTENSION ) ) && class_exists( 'ZipArchive' ) ) {
		$zip = new ZipArchive();
		if ( true === $zip->open( $archive ) ) {
			$data = $zip->getFromName( $member );
			$zip->close();
			return $data;
		}
		return false;
	}
	if ( class_exists( 'PharData' ) ) {
		try {
			$tar = new PharData( $archive );
			if ( isset( $tar[ $member ] ) ) {
				return $tar[ $member ]->getContent();
			}
		} catch ( Exception $e ) {
			return false;
		}
	}
	return false;
}

/**
 * Restore one original file to $dest_abs (basedir + $rel).
 * Order: existing file -> quarantine -> backup archive -> still missing.
 * Returns 'kept' | 'quarantine' | 'archive' | 'missing'.
 */
function mo_restore_file( $rel, $dest_abs, $quarantine_dir, $archive, $dry_run ) {
	if ( is_file( $dest_abs ) ) {
		return 'kept'; // original still in place — nothing to do
	}

	$flat = mo_quarantine_name( $rel );
	$qsrc = $quarantine_dir . $flat;
	if ( is_file( $qsrc ) ) {
		if ( ! $dry_run ) {
			wp_mkdir_p( dirname( $dest_abs ) );
			if ( ! @rename( $qsrc, $dest_abs ) ) {
				return 'missing';
			}
		}
		return 'quarantine';
	}

	if ( null !== $archive && '' !== $archive ) {
		$data = mo_archive_read( $archive, $rel );
		if ( false !== $data ) {
			if ( ! $dry_run ) {
				wp_mkdir_p( dirname( $dest_abs ) );
				if ( false === file_put_contents( $dest_abs, $data ) ) {
					return 'missing';
				}
			}
			return 'archive';
		}
	}

	return 'missing';
}

/* ------------------------------------------------------------------ */
/* Plan the reversal                                                   */
/* ------------------------------------------------------------------ */

$archive        = isset( $manifest['backup_archive'] ) ? $manifest['backup_archive'] : null;
$quarantine_dir = $basedir . '_legacy_quarantine/';

$plan    = array();
$skipped = array();

foreach ( $manifest['items'] as $item ) {
	$id = isset( $item['attachment_id'] ) ? (int) $item['attachment_id'] : 0;
	if ( ! $id ) {
		$skipped[] = array( 'item' => wp_json_encode( $item ), 'reason' => 'no attachment_id' );
		continue;
	}
	if ( empty( $item['original_path'] ) ) {
		$skipped[] = array( 'attachment_id' => $id, 'reason' => 'no original_path' );
		continue;
	}

	// Files to restore: every converted file's original src, as a
	// rel path under the uploads dir plus its absolute destination.
	$files_back = array();
	$webp_del   = array();
	if ( ! empty( $item['files'] ) && is_array( $item['files'] ) ) {
		foreach ( $item['files'] as $role => $r ) {
			if ( ! is_array( $r ) || 'converted' !== ( isset( $r['status'] ) ? $r['status'] : '' ) ) {
				continue;
			}
			$src_abs = isset( $r['src'] ) ? $r['src'] : null;
			if ( $src_abs ) {
				$rel = ltrim( str_replace( $basedir, '', $src_abs ), '/\\' );
				$files_back[] = array( 'role' => $role, 'rel' => $rel, 'dest' => $src_abs );
			}
			if ( ! empty( $r['dst'] ) ) {
				$webp_del[] = $r['dst'];
			}
		}
	}
	// Fallback when the manifest has no per-file breakdown.
	if ( empty( $files_back ) ) {
		$files_back[] = array(
			'role' => 'full',
			'rel'  => $item['original_path'],
			'dest' => $basedir . $item['original_path'],
		);
	}
	if ( ! empty( $item['webp_path'] ) ) {
		$webp_del[] = $basedir . $item['webp_path'];
	}

	$plan[] = array(
		'id'             => $id,
		'original_path'  => $item['original_path'],
		'webp_path'      => isset( $item['webp_path'] ) ? $item['webp_path'] : null,
		'previous_mime'  => isset( $item['previous_mime'] ) ? $item['previous_mime'] : null,
		'previous_meta'  => isset( $item['previous_metadata'] ) && is_array( $item['previous_metadata'] ) ? $item['previous_metadata'] : null,
		'affected_posts' => isset( $item['affected_posts'] ) && is_array( $item['affected_posts'] ) ? $item['affected_posts'] : array(),
		'url_rewrites'   => isset( $item['url_rewrites'] ) && is_array( $item['url_rewrites'] ) ? $item['url_rewrites'] : array(),
		'files_back'     => $files_back,
		'webp_del'       => array_unique( $webp_del ),
	);
}

WP_CLI::log( sprintf( 'Attachments to roll back: %d | skipped: %d%s',
	count( $plan ),
	count( $skipped ),
	$opt['dry_run'] ? ' | DRY RUN' : ''
) );

global $wpdb;

$restored_files = 0;
$restored_posts = 0;
$restored_items = 0;

foreach ( $plan as $p ) {
	$id = $p['id'];

	/* --- Stage 1: put the original files back ------------------------ */
	$file_status = array();
	foreach ( $p['files_back'] as $fb ) {
		$file_status[ $fb['role'] ] = mo_restore_file(
			$fb['rel'],
			$fb['dest'],
			$quarantine_dir,
			$archive,
			$opt['dry_run']
		);
		if ( 'missing' !== $file_status[ $fb['role'] ] ) {
			$restored_files++;
		}
	}
	$missing = array_keys( $file_status, 'missing' );

	/* --- Stage 2: database restore ----------------------------------- */
	if ( ! $opt['dry_run'] ) {
		if ( $p['previous_mime'] ) {
			$wpdb->update( $wpdb->posts, array( 'post_mime_type' => $p['previous_mime'] ), array( 'ID' => $id ) );
		}
		update_post_meta( $id, '_wp_attached_file', $p['original_path'] );
		if ( null !== $p['previous_meta'] ) {
			update_post_meta( $id, '_wp_attachment_metadata', $p['previous_meta'] );
		}
	}

	/* --- Stage 3: revert post_content URLs --------------------------- */
	// Invert the new->old map: strtr swaps the .webp URLs back to the
	// originals; alt/title attributes are untouched either way.
	$reverse_map = array();
	foreach ( $p['url_rewrites'] as $old_url => $new_url ) {
		$reverse_map[ $new_url ] = $old_url;
	}

	foreach ( $p['affected_posts'] as $post_id ) {
		$post_id = (int) $post_id;
		$content = $wpdb->get_var( $wpdb->prepare( "SELECT post_content FROM {$wpdb->posts} WHERE ID = %d", $post_id ) );
		if ( null === $content || empty( $reverse_map ) ) {
			continue;
		}
		$reverted = strtr( $content, $reverse_map );
		if ( $reverted !== $content ) {
			if ( ! $opt['dry_run'] ) {
				$wpdb->update( $wpdb->posts, array( 'post_content' => $reverted ), array( 'ID' => $post_id ) );
			}
			$restored_posts++;
		}
	}

	/* --- Stage 4: remove the generated webp files --------------------- */
	if ( ! $opt['dry_run'] ) {
		foreach ( $p['webp_del'] as $webp ) {
			if ( is_file( $webp ) ) {
				@unlink( $webp );
			}
		}
	}

	$restored_items++;
	WP_CLI::log( sprintf(
		'  [#%d] %s | files: %s | content posts: %d%s',
		$id,
		$p['original_path'],
		wp_json_encode( $file_status ),
		count( $p['affected_posts'] ),
		empty( $missing ) ? '' : ' | MISSING: ' . implode( ',', $missing )
	) );
}

WP_CLI::success( sprintf(
	'%s %d attachments | %d files restored | %d post_content reverted%s',
	$opt['dry_run'] ? 'Would roll back:' : 'Rolled back:',
	$restored_items,
	$restored_files,
	$restored_posts,
	empty( $archive ) ? ' | (no backup_archive in manifest)' : ''
) );
